import { NextRequest, NextResponse } from 'next/server';
import { getSupabaseAdmin } from '@/lib/supabase/admin';
import { verifyVerificationToken } from '@/lib/auth-token';

/**
 * POST /api/auth/verify-link
 *
 * Verifies a user's email using the secure token generated by /api/auth/send-verification.
 * Atomically updates both public.profiles.email_verified and auth.users email_confirmed_at.
 */
export async function POST(req: NextRequest) {
  try {
    const body = await req.json().catch(() => ({}));
    const { token } = body as { token?: string };

    if (!token || typeof token !== 'string') {
      return NextResponse.json(
        { success: false, error: 'Verification token is required.' },
        { status: 400 }
      );
    }

    const payload = verifyVerificationToken(token);
    if (!payload) {
      return NextResponse.json(
        {
          success: false,
          error: 'Verification link is invalid or has expired. Please request a new confirmation email from your profile.',
        },
        { status: 400 }
      );
    }

    const adminClient = getSupabaseAdmin();

    // 1. Call atomic database RPC to update profiles and auth.users
    const { data: rpcData, error: rpcError } = await adminClient.rpc('verify_user_email', {
      target_user_id: payload.userId,
    });

    if (rpcError) {
      console.error('[verify-link] RPC error, falling back to direct table update:', rpcError);
      // Fallback direct update
      await adminClient
        .from('profiles')
        .update({ email_verified: true, updated_at: new Date().toISOString() })
        .eq('id', payload.userId);

      await adminClient.auth.admin.updateUserById(payload.userId, {
        email_confirm: true,
        user_metadata: { email_verified: true },
      }).catch((e) => console.warn('[verify-link] updateUserById fallback warning:', e));
    }

    // 2. Fetch updated profile to return role and name
    const { data: profile } = await adminClient
      .from('profiles')
      .select('id, full_name, email, role, email_verified')
      .eq('id', payload.userId)
      .maybeSingle();

    return NextResponse.json({
      success: true,
      message: 'Email address verified successfully!',
      user: {
        id: payload.userId,
        email: payload.email,
        fullName: profile?.full_name,
        role: profile?.role || 'customer',
        email_verified: true,
      },
    });
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : 'Failed to verify email link.';
    console.error('[verify-link] Error:', err);
    return NextResponse.json({ success: false, error: msg }, { status: 500 });
  }
}
